// Package postgres implements the identity module's storage ports with the
// queries in queries.sql (generated by sqlc into sqlcgen/).
package postgres

import (
	"context"
	"errors"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"

	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/identity/adapters/postgres/sqlcgen"
	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/identity/app"
	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/identity/domain"
	"github.com/AtmosferaSoltec/atm-km-api/internal/platform/tx"
)

const uniqueViolation = "23505"

// DB gives the ongoing transaction's connection, or the pool (tx.Runner).
type DB interface {
	DB(ctx context.Context) tx.DBTX
}

// Users implements app.Users.
type Users struct {
	db DB
}

// NewUsers creates the accounts repository.
func NewUsers(db DB) Users { return Users{db: db} }

func (r Users) q(ctx context.Context) *sqlcgen.Queries { return sqlcgen.New(r.db.DB(ctx)) }

// Create stores the account; the unique index on username decides if it exists.
func (r Users) Create(ctx context.Context, user domain.User) error {
	err := r.q(ctx).CreateUser(ctx, sqlcgen.CreateUserParams{
		ID: user.ID, Username: user.Username, DisplayName: user.DisplayName,
		PasswordHash: user.PasswordHash, IsActive: user.IsActive, CreatedAt: user.CreatedAt,
	})
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) && pgErr.Code == uniqueViolation {
		return domain.ErrUsernameTaken
	}
	return err
}

// ByUsername finds an account by its normalized username.
func (r Users) ByUsername(ctx context.Context, username string) (domain.User, error) {
	row, err := r.q(ctx).GetUserByUsername(ctx, username)
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.User{}, domain.ErrNotFound
	}
	if err != nil {
		return domain.User{}, err
	}
	return domain.User{
		ID: row.ID, Username: row.Username, DisplayName: row.DisplayName,
		PasswordHash: row.PasswordHash, IsActive: row.IsActive, CreatedAt: row.CreatedAt,
	}, nil
}

// ByID finds an account by its id.
func (r Users) ByID(ctx context.Context, id uuid.UUID) (domain.User, error) {
	row, err := r.q(ctx).GetUserByID(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.User{}, domain.ErrNotFound
	}
	if err != nil {
		return domain.User{}, err
	}
	return domain.User{
		ID: row.ID, Username: row.Username, DisplayName: row.DisplayName,
		PasswordHash: row.PasswordHash, IsActive: row.IsActive, CreatedAt: row.CreatedAt,
	}, nil
}

// TouchLastLogin records the last login.
func (r Users) TouchLastLogin(ctx context.Context, id uuid.UUID) error {
	return r.q(ctx).TouchLastLogin(ctx, id)
}

// SetPassword stores the new password hash.
func (r Users) SetPassword(ctx context.Context, id uuid.UUID, hash string) error {
	return r.q(ctx).UpdatePassword(ctx, sqlcgen.UpdatePasswordParams{ID: id, PasswordHash: hash})
}

// SetActive turns the account on or off.
func (r Users) SetActive(ctx context.Context, id uuid.UUID, active bool) error {
	return r.q(ctx).SetUserActive(ctx, sqlcgen.SetUserActiveParams{ID: id, IsActive: active})
}

// Sessions implements app.Sessions.
type Sessions struct {
	db DB
}

// NewSessions creates the sessions repository.
func NewSessions(db DB) Sessions { return Sessions{db: db} }

func (r Sessions) q(ctx context.Context) *sqlcgen.Queries { return sqlcgen.New(r.db.DB(ctx)) }

// Create opens a session.
func (r Sessions) Create(ctx context.Context, session app.Session) error {
	var userAgent *string
	if session.UserAgent != "" {
		userAgent = &session.UserAgent
	}
	return r.q(ctx).CreateSession(ctx, sqlcgen.CreateSessionParams{
		ID: session.ID, UserID: session.UserID, UserAgent: userAgent, IsWeb: session.Web,
	})
}

// IsActive tells whether the session exists, belongs to the user, is not
// revoked and the user is still active.
func (r Sessions) IsActive(ctx context.Context, sessionID, userID uuid.UUID) (bool, error) {
	return r.q(ctx).IsSessionActive(ctx, sqlcgen.IsSessionActiveParams{ID: sessionID, UserID: userID})
}

// Revoke closes the session with its reason.
func (r Sessions) Revoke(ctx context.Context, sessionID uuid.UUID, reason string) error {
	return r.q(ctx).RevokeSession(ctx, sqlcgen.RevokeSessionParams{ID: sessionID, RevokedReason: &reason})
}

// RevokeAll closes every session of the user.
func (r Sessions) RevokeAll(ctx context.Context, userID uuid.UUID, reason string) error {
	return r.q(ctx).RevokeUserSessions(ctx, sqlcgen.RevokeUserSessionsParams{UserID: userID, RevokedReason: &reason})
}

// Touch records the last use.
func (r Sessions) Touch(ctx context.Context, sessionID uuid.UUID) error {
	return r.q(ctx).TouchSession(ctx, sessionID)
}

// CreateRefreshToken stores a refresh token's hash.
func (r Sessions) CreateRefreshToken(ctx context.Context, token app.RefreshToken) error {
	return r.q(ctx).CreateRefreshToken(ctx, sqlcgen.CreateRefreshTokenParams{
		ID: token.ID, SessionID: token.SessionID, TokenHash: token.Hash, ExpiresAt: token.ExpiresAt,
	})
}

// LockRefreshToken locks the token until the transaction ends.
func (r Sessions) LockRefreshToken(ctx context.Context, hash []byte) (app.LockedRefreshToken, error) {
	row, err := r.q(ctx).LockRefreshToken(ctx, hash)
	if errors.Is(err, pgx.ErrNoRows) {
		return app.LockedRefreshToken{}, domain.ErrNotFound
	}
	if err != nil {
		return app.LockedRefreshToken{}, err
	}
	return app.LockedRefreshToken{
		ID:             row.ID,
		SessionID:      row.SessionID,
		UserID:         row.UserID,
		Web:            row.IsWeb,
		ExpiresAt:      row.ExpiresAt,
		UsedAt:         row.UsedAt,
		SessionRevoked: row.SessionRevokedAt != nil,
		UserActive:     row.UserActive,
	}, nil
}

// MarkRefreshTokenUsed marks the token as used (rotation).
func (r Sessions) MarkRefreshTokenUsed(ctx context.Context, id uuid.UUID, now time.Time) error {
	return r.q(ctx).MarkRefreshTokenUsed(ctx, sqlcgen.MarkRefreshTokenUsedParams{ID: id, UsedAt: &now})
}

// Prune deletes expired refresh tokens and the sessions left without any.
func (r Sessions) Prune(ctx context.Context, now time.Time, staleAfter time.Duration) (int64, error) {
	q := r.q(ctx)
	tokens, err := q.DeleteExpiredRefreshTokens(ctx, now)
	if err != nil {
		return 0, err
	}
	sessions, err := q.DeleteStaleSessions(ctx, now.Add(-staleAfter))
	return tokens + sessions, err
}
